export default function Footer() {
  const [showTopBtn, setShowTopBtn] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setShowTopBtn(window.scrollY > 400);
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  return (
    <footer className="w-full bg-[#E7EDEA] rounded-t-[16px] sm:rounded-t-[20px] py-7 sm:py-8 lg:py-9">
      <Container>
        <div className="flex flex-col md:flex-row items-center justify-between gap-6 sm:gap-8">
          {/* Left Section: Logo + Navigation Links */}
          <div className="flex flex-col sm:flex-row items-center gap-6 sm:gap-8 lg:gap-10">
            {/* App Logo */}
            <Link
              href={footerData.logo.href}
              className="flex items-center shrink-0 select-none"
            >
              <Image
                src={footerData.logo.src}
                alt={footerData.logo.alt}
                width={footerData.logo.width}
                height={footerData.logo.height}
                className="h-[22px] sm:h-[24px] w-auto object-contain"
              />
            </Link>

            {/* Footer Navigation Links */}
            <nav className="flex items-center space-x-6 sm:space-x-7 lg:space-x-8">
              {footerData.links.map((link) => (
                <a
                  key={link.label}
                  href={link.href}
                  className="text-[13px] sm:text-sm font-bold text-[#194536] hover:text-black transition-colors whitespace-nowrap"
                >
                  {link.label}
                </a>
              ))}
            </nav>
          </div>

          {/* Right Section: Social Media Icons + Copyright */}
          <div className="flex flex-col items-center md:items-end gap-2 text-right">
            {/* Social Media Icons */}
            <div className="flex items-center space-x-3.5 sm:space-x-4 text-[#194536]">
              {footerData.socials.map((social) => (
                <a
                  key={social.name}
                  href={social.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label={social.ariaLabel}
                  title={social.name}
                  className="hover:opacity-70 transition-opacity flex items-center justify-center p-0.5"
                >
                  <SocialIcon icon={social.icon} />
                </a>
              ))}
            </div>

            {/* Copyright Text */}
            <p className="text-[12px] sm:text-[13px] text-[#194536]/75 font-normal tracking-tight">
              {footerData.copyright}
            </p>
          </div>
        </div>
      </Container>

      {/* Floating Back to Top Button */}
      {showTopBtn && (
        <button
          onClick={scrollToTop}
          className="fixed bottom-6 left-6 z-40 p-3 bg-white text-zinc-900 rounded-full shadow-lg border border-zinc-200/80 hover:bg-zinc-50 hover:shadow-xl transition-all duration-300 hover:-translate-y-1 cursor-pointer"
          aria-label="Back to top"
        >
          <svg
            className="w-5 h-5"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="2"
              d="M5 10l7-7m0 0l7 7m-7-7v18"
            />
          </svg>
        </button>
      )}
    </footer>
  );
}
